'use client'

import type { ProductVariant } from '@/lib/vendor/catalog'

export function VariantEditor({ variants, onChange }: { variants: ProductVariant[]; onChange: (variants: ProductVariant[]) => void }) { function update(id: string, field: keyof ProductVariant, value: string) { onChange(variants.map((variant) => variant.id === id ? { ...variant, [field]: field === 'price' || field === 'stock' ? Number(value) : value } : variant)) } return <div className="variant-editor"><div className="variant-editor-head"><div><p className="vendor-eyebrow">Optional</p><h3>Variants</h3></div><button type="button" className="btn-skip" onClick={() => onChange([...variants, { id: crypto.randomUUID(), name: '', sku: '', price: 0, stock: 0, option: '' }])}>Add variant</button></div>{variants.length ? variants.map((variant) => <div className="variant-row" key={variant.id}><input value={variant.name} onChange={(event) => update(variant.id, 'name', event.target.value)} placeholder="Variant name" /><input value={variant.option} onChange={(event) => update(variant.id, 'option', event.target.value)} placeholder="Option e.g. Walnut" /><input value={variant.sku} onChange={(event) => update(variant.id, 'sku', event.target.value)} placeholder="SKU" /><input type="number" min="0" value={variant.price} onChange={(event) => update(variant.id, 'price', event.target.value)} placeholder="Price" /><input type="number" min="0" value={variant.stock} onChange={(event) => update(variant.id, 'stock', event.target.value)} placeholder="Stock" /><button type="button" onClick={() => onChange(variants.filter((item) => item.id !== variant.id))}>Remove</button></div>) : <p className="variant-empty">No variants added. Use this for products with size, color, or material options.</p>}</div> }